  <div class="app-shell">
    <canvas class="viewport" aria-label="Inflate pillow viewport"></canvas>
    <section id="ui-panel" class="apple-panel" aria-label="Inflate pillow controls">
      <div id="ui-handle" class="panel-drag-handle">
        <button
          id="collapseToggle"
          class="collapse-button panel-collapse-toggle"
          type="button"
          aria-label="Collapse controls"
          aria-expanded="true"
        >
          <span class="collapse-icon" aria-hidden="true"></span>
        </button>
      </div>
      <div class="ui-body panel-sections">
        <div class="control-hint">Wheel = Zoom, MMB = Pan, RMB = Orbit</div>
        <section class="panel-section">
          <button class="panel-section-header" type="button" aria-expanded="true">
            <span class="panel-section-label">Simulation</span>
          </button>
          <div class="panel-section-content panel-controls-stack">
            <div class="control control-grid-2">
              <button id="inflateButton" class="pill-button action-button" type="button">Start</button>
              <button id="resetButton" class="pill-button reset-button" type="button">Reset</button>
            </div>
            <label class="control" for="pressureSlider">
              <div class="control-row">
                <span>Pressure</span>
                <span id="pressure-value">0.42</span>
              </div>
              <input id="pressureSlider" type="range" min="0" max="1" value="0.42" step="0.01" />
            </label>
            <label class="control" for="subdivisionSlider">
              <div class="control-row">
                <span>Subdivision</span>
                <span id="subdivision-value">1</span>
              </div>
              <input id="subdivisionSlider" type="range" min="0" max="2" value="1" step="1" />
            </label>
          </div>
        </section>
        <section class="panel-section">
          <button class="panel-section-header" type="button" aria-expanded="true">
            <span class="panel-section-label">Import</span>
          </button>
          <div class="panel-section-content panel-controls-stack">
            <div class="control">
              <button id="importObjButton" class="pill-button control-button-wide" type="button">Import OBJ</button>
              <input id="importObjInput" type="file" accept=".obj,text/plain,model/obj" hidden />
            </div>
            <div id="import-status" class="control-hint">No OBJ loaded (drawing on base plane).</div>
          </div>
        </section>
        <section class="panel-section">
          <button class="panel-section-header" type="button" aria-expanded="true">
            <span class="panel-section-label">Seams</span>
          </button>
          <div class="panel-section-content panel-controls-stack">
            <div class="control-hint seam-hints">
              LMB = Draw Seam (on OBJ if loaded)<br />
              Enter = Finish Seam<br />
              Connect to Start = Finish Seam<br />
              LMB+Drag on Corner = Move Corner<br />
              LMB Closed Shape = Inner Seam Mode (projected)<br />
              LMB Inflated = Push Mesh
            </div>
            <label class="control" for="outerSeamCurvature">
              <div class="control-row">
                <span>Outer Seam Curvature</span>
                <span id="outer-seam-curvature-value">1</span>
              </div>
              <input id="outerSeamCurvature" type="range" min="1" max="12" value="1" step="1" />
            </label>
            <label class="control" for="innerSeamCurvature">
              <div class="control-row">
                <span>Inner Seam Curvature</span>
                <span id="inner-seam-curvature-value">1</span>
              </div>
              <input id="innerSeamCurvature" type="range" min="1" max="12" value="1" step="1" />
            </label>
            <div class="control control-grid-2">
              <button id="undoButton" class="pill-button" type="button">Undo</button>
              <button id="redoButton" class="pill-button" type="button">Redo</button>
            </div>
          </div>
        </section>
        <section class="panel-section">
          <button class="panel-section-header" type="button" aria-expanded="true">
            <span class="panel-section-label">Display</span>
          </button>
          <div class="panel-section-content panel-controls-stack">
            <label class="toggle-control" for="seamCurvesToggle">
              <span>Seam Curves</span>
              <input id="seamCurvesToggle" type="checkbox" checked />
            </label>
            <label class="toggle-control" for="baseGridToggle">
              <span>Base Grid</span>
              <input id="baseGridToggle" type="checkbox" checked />
            </label>
            <label class="toggle-control" for="wireToggle">
              <span>Mesh Wires</span>
              <input id="wireToggle" type="checkbox" checked />
            </label>
            <label class="toggle-control" for="reflectionToggle">
              <span>Foil Material</span>
              <input id="reflectionToggle" type="checkbox" checked />
            </label>
          </div>
        </section>
        <section class="panel-section">
          <button class="panel-section-header" type="button" aria-expanded="true">
            <span class="panel-section-label">Export</span>
          </button>
          <div class="panel-section-content panel-controls-stack">
            <div class="control">
              <button id="exportObjButton" class="pill-button control-button-wide" type="button">Export OBJ</button>
            </div>
            <div class="control">
              <button id="exportGlbButton" class="pill-button control-button-wide" type="button">Export GLB</button>
            </div>
            <div class="control">
              <button id="exportScreenshotButton" class="pill-button control-button-wide" type="button">Export Screenshot</button>
            </div>
          </div>
        </section>
      </div>
      <div id="ui-handle-bottom"></div>
    </section>
  </div>
